  for(const e of t.Data.Events){
   if(starts[e.Monster]===undefined)starts[e.Monster]=r;
   if(e.Target?.startsWith('character:')&&e.HpAfter!==null&&e.TargetMaxHp>0){const i=+e.Target.split(':')[1]-1;minimum[i]=Math.min(minimum[i],100*e.HpAfter/e.TargetMaxHp);}
   assert(!e.SkillCode?.startsWith('depth-placeholder-')&&!e.SkillCode?.startsWith('endgame-')&&!e.SkillCode?.startsWith('widow-'));
   assert.notEqual(e.ActionKind,2,'No soul imprint');
   if(e.Kind===0&&e.ActionKind===0&&e.Source?.startsWith('monster:')){
    const spec=skillSpec[e.SkillCode];assert(spec);assert(r-starts[e.Source]+1>=spec[0]);
    const key=e.Source+e.SkillCode;if(!committed.has(key)){
     const prior=s.RoundTrace[ti-1]?.Data.MonsterCooldowns.find(c=>c.Actor===e.Source&&c.SkillCode===e.SkillCode);
     if(prior)assert(r>=prior.ReadyAtRound);
     assert.equal(t.Data.MonsterCooldowns.find(c=>c.Actor===e.Source&&c.SkillCode===e.SkillCode)?.ReadyAtRound,r+spec[1]);committed.add(key);
    }
   }
   if(e.Status?.Code===plague){
