    if(e.StatusChange===0){
     assert.equal(start,null);assert.equal(st.Stacks,1);assert.equal(st.AppliedRound,r);assert.equal(st.ExpiresAfterRound,r+3);
     const prior=s.RoundTrace[ti-1].Data;
     assert(prior.Monsters.find(m=>m.Actor===boss).Hp<=s.InitialMonsters[4].MaxHp*.7,'Activation after committed HP crossing');
     const modifiers=prior.Statuses.filter(st=>st.Target===boss&&st.ExpiresAfterRound>=r).reduce((n,st)=>{
      const d=definitions.get(st.EffectCode);return n+(d?.EffectType==='AttackPercent'?(st.MagnitudeSnapshot??d.ValuePerStack)*st.Stacks:0);},0);
     assert.equal(st.PerTickValue,Math.max(1,Math.floor(s.InitialMonsters[4].Attack*Math.max(0,1+modifiers/100)*.1)));
     active=true;start=r;target=e.Target;layers=1;unit=st.PerTickValue;progress=0;
     assert.equal(target,'character:1');
    }else if(e.StatusChange===1){
     assert(active&&tickThisRound);assert.equal(st.AppliedRound,start);assert.equal(st.ExpiresAfterRound,start+3);
     assert.equal(st.PerTickValue,unit);assert.equal(st.Stacks,layers+1);assert.equal(st.Stacks,r-start+2);
     layers=st.Stacks;growth.push({Round:r,Stacks:layers});
    }else if(e.StatusChange===3){
     assert(active);assert.equal(e.Target,target);end=r;
     if(e.Kind===3){assert.equal(e.SkillCode,'acolyte-purify');method='Cleanse';}
     else if(e.Source?.startsWith('character:')){assert(progress>=threshold);method='LightDamage';}
     else{assert.equal(r,start+3);assert(tickThisRound);method='NaturalExpiry';}
     active=false;
    }
   }
   if(active&&e.Kind===0&&e.Source?.startsWith('character:')&&e.Target===boss&&e.Element===4&&e.ActualAmount>0&&[0,1,3,4,6].includes(e.ActionKind))progress+=e.ActualAmount;
   if(e.Kind===0&&e.ActionKind===5&&e.SkillCode==='plague-poison-tick'){
    assert(active&&!tickThisRound);assert.equal(e.Target,target);assert.equal(e.Source,boss);
    assert.equal(layers,r-start+1);assert.equal(e.CalculatedAmount,unit*layers);assert.equal(e.ActualAmount,Math.min(e.HpBefore,unit*layers));
    assert(!e.IsCritical&&e.Element===null&&e.ElementModifier===0);tickThisRound=true;poisonTicks++;poisonDamage+=e.ActualAmount;
    ticks.push({Round:r,Stacks:layers,Damage:e.ActualAmount});
   }
   if(e.Status?.Code===reward&&e.StatusChange===0){
    assert(!active&&method!=='NaturalExpiry');assert.equal(e.Target,target);assert.equal(r,end+1);assert.equal(e.Status.ExpiresAfterRound,r+2);
    assert(e.Status.IsPositive&&!e.Status.CanDispel);assert.equal(e.Status.BoundTarget,boss);rewardStart=r;rewardEnd=r+2;rewardApplied++;
   }
   if(e.Status?.Code===basic){
