     assert.equal(st.ExpiresAfterRound,r+2);
     if(e.StatusChange===0)assert.equal(st.AppliedRound,r);
     else if(basicStates.has(e.Target)){const old=basicStates.get(e.Target);assert.equal(st.AppliedRound,old.AppliedRound);assert(st.PerTickValue>=old.PerTickValue);}
     basicStates.set(e.Target,st);
    }else if([3,4].includes(e.StatusChange)){if(e.Kind===3)basicCleanses++;basicStates.delete(e.Target);}
   }
   if(e.Kind===0&&e.ActionKind===5&&e.Source?.startsWith('monster:')&&e.SkillCode!=='plague-poison-tick'){
    const st=basicStates.get(e.Target);assert(st);assert(r>st.AppliedRound&&r<=st.ExpiresAfterRound);
    assert.equal(e.CalculatedAmount,st.PerTickValue);assert.equal(e.ActualAmount,Math.min(e.HpBefore,st.PerTickValue));
    assert(!e.IsCritical&&e.Element===null);basicTicks++;basicDamage+=e.ActualAmount;
   }
  }
  const states=t.Data.Statuses;
  for(const key of basicStates.keys())if(!states.some(st=>st.Target===key&&st.EffectCode===basic))basicStates.delete(key);
  if(start!==null&&t.Data.Events.some(e=>e.Monster===boss)){
   const p=phaseFacts.find(p=>p.LocalRound===r-starts[boss]+1);assert(p);assert.equal(p.Activations,1);assert.equal(p.WaterDamage,progress);
   assert.equal(p.IsActive,active);
   if(rewardStart!==null&&r>=rewardStart&&r<=rewardEnd)rewardRounds.push(r);
  }
 }
 assert.equal(last.Activations,1);assert(!active);assert.equal(last.WaterDamage,progress);
 assert.equal(last.LastActivationRound,start);assert.equal(last.Breaks,method==='NaturalExpiry'?0:1);assert.equal(last.Expiries,method==='NaturalExpiry'?1:0);
 if(method==='NaturalExpiry'){assert.equal(poisonTicks,4);assert.equal(poisonDamage,10*unit);assert.equal(rewardApplied,0);assert.equal(last.LastExpiryRound,end);}
 else{assert.equal(last.LastBreakRound,end);assert.equal(rewardApplied,1);assert.deepEqual(rewardRounds,[end+1,end+2,end+3]);}
 if(route==='unhandled')assert.equal(method,'NaturalExpiry');
 if(route==='cleanse-only'){assert(['Cleanse','NaturalExpiry'].includes(method));if(method==='NaturalExpiry'){for(const t of s.RoundTrace.filter(t=>t.Data.RoundNumber-1>=start&&t.Data.RoundNumber-1<=end)){const cd=t.Data.CharacterCooldowns?.find(c=>c.Actor==='character:2'&&c.SkillCode==='acolyte-purify');assert(cd&&cd.ReadyAtRound>t.Data.RoundNumber-1,'Natural expiry is an actual cleanse cooldown miss');}}}
 if(route==='light-only'||route==='light-mage')assert.equal(method,'LightDamage');
 return {MinimumHpPercentBySlot:minimum,StartRound:start,EndRound:end,WindowRoundAtEnd:end-start+1,Method:method,
  ActualLightDamage:progress,RequiredLightDamage:threshold,AttackSnapshotPerStack:unit,PoisonTicks:poisonTicks,PoisonDamage:poisonDamage,
  Growth:growth,Ticks:ticks,RewardRounds:rewardRounds,BasicPoisonTicks:basicTicks,BasicPoisonDamage:basicDamage,BasicPoisonCleanses:basicCleanses,
  NoLifeErosionOrLethalStack:true,SnapshotGrowthAndFourFullRoundWindowVerified:true,RewardThreeFullRoundsVerified:method!=='NaturalExpiry',BasicPoisonSuppressionVerified:true,SkillCooldownsVerified:true};
};
if(require.main===module){for(const n of ['main','light-only','cleanse-only','unhandled','light-mage']){const j=JSON.parse(fs.readFileSync(__dirname+'/final-'+n+'.json'));const a=j.Samples.map(s=>module.exports(s,n));console.log(JSON.stringify({Scenario:n,Runs:a.length,Methods:a.reduce((m,x)=>(m[x.Method]=(m[x.Method]??0)+1,m),{}),Windows:a.reduce((m,x)=>(m[x.WindowRoundAtEnd]=(m[x.WindowRoundAtEnd]??0)+1,m),{}),MinTank:Math.min(...a.map(x=>x.MinimumHpPercentBySlot[0]))}));}}
